    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Fiebre intermitente\n🧠 ANÁLISIS DE LA PREGUNTALa fiebre intermitente presenta períodos de temperatura elevada separados por períodos de temperatura normal. La fiebre sostenida permanece elevada con escasa variación diaria, mientras que la remitente fluctúa de manera importante pero permanece persistentemente elevada.\n🔑 CONCEPTOS CLAVE\nIntermitente: incluye períodos de temperatura normal.\nSostenida: persistente, con variación ≤0,5 °C/día.\nRemitente: persistente, con variación >0,5 °C/día.\nRecurrente: períodos febriles separados por intervalos de temperatura normal.\nTerciaria: fiebre en el primer y tercer día.\nCuartana: fiebre en el primer y cuarto día.\n⚡ REPASO ACTIVOIntermitente = vuelve a temperatura normal.Remitente = fluctúa, pero permanece elevada.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 219, pág. 1640.",
