    "explanation": "Respuesta correcta: No tratar la fiebre únicamente con el objetivo de normalizar la temperatura\n🧠 ANÁLISIS DE LA PREGUNTALa fiebre es una respuesta adaptativa y no necesita tratarse únicamente para devolver la temperatura corporal a valores normales en un niño sano. El tratamiento puede utilizarse cuando el aumento de temperatura produce malestar.\n🔑 CONCEPTOS CLAVE\nLa fiebre <39 °C en niños sanos generalmente no requiere tratamiento.\nEl objetivo principal de la evaluación y tratamiento es determinar la causa subyacente.\nEl tratamiento de la fiebre puede indicarse para mejorar el confort cuando la temperatura aumenta.\nNo existe evidencia de que la fiebre alta produzca daño cerebral, excepto en situaciones poco frecuentes como estatus epiléptico febril y golpe de calor.\n⚡ REPASO ACTIVONiño sano + fiebre <39 °C + buen estado general → no tratar solo el número del termómetro. El foco principal es identificar la causa de la fiebre.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 219, pág. 1641.",
