    "id": "semana17_ped_q039",
    "text": "Un paciente presenta años después de haber padecido sarampión deterioro intelectual progresivo, alteraciones conductuales y mioclonías. ¿Cuál es el diagnóstico más probable?",
    "options": [
      "Encefalitis aguda por sarampión",
      "Encefalitis postinfecciosa",
      "Síndrome de Guillain-Barré",
      "Panencefalitis esclerosante subaguda",
      "Meningoencefalitis bacteriana"
    ],
    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Panencefalitis esclerosante subaguda\n🧠 ANÁLISIS DE LA PREGUNTALa panencefalitis esclerosante subaguda (PEES) es una complicación crónica del sarampión causada por una infección persistente con virus alterado. Suele aparecer 7-10 años después de la infección y produce deterioro neurológico progresivo.\n🔑 CONCEPTOS CLAVE\nComplicación crónica del sarampión.\nAparece habitualmente 7-10 años después.\nManifestaciones iniciales:\nCambios sutiles de conducta.\nDisminución del rendimiento escolar.\nIrritabilidad.\nReducción de la atención.\nAlteraciones del temperamento.\nPosteriormente aparecen:\nMioclonías.\nConvulsiones.\nDeterioro neurológico progresivo.\nLa evolución conduce inexorablemente a neurodegeneración progresiva.\n⚡ REPASO ACTIVOSarampión → años después + deterioro escolar/conductual + mioclonías = PEES.\nPerla: la latencia típica es 7-10 años.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, págs. 1961-1962.",
