    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Adenopatías retroauriculares, suboccipitales y cervicales posteriores\n🧠 ANÁLISIS DE LA PREGUNTALa linfadenopatía retroauricular, suboccipital y cervical posterior constituye uno de los hallazgos clínicos más prominentes de la rubéola. En niños puede ser la primera manifestación de la enfermedad.\n🔑 CONCEPTOS CLAVE\nLa infección posnatal suele ser una enfermedad leve.\nPeríodo de incubación: 16-18 días.\nPródromo en niños: habitualmente ausente o leve.\nPuede presentar:\nFiebre baja.\nDolor de garganta.\nOjos rojos.\nCefalea.\nMalestar.\nAnorexia.\nLinfadenopatía.\nAdenopatías características: suboccipitales, retroauriculares y cervicales posteriores.\n⚡ REPASO ACTIVORubéola + adenopatías retroauriculares/suboccipitales = asociación clásica.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, págs. 1965-1966.",
