    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Primeras 8 semanas de gestación\n🧠 ANÁLISIS DE LA PREGUNTALa infección materna por rubéola durante las primeras 8 semanas de gestación representa el período de mayor riesgo para el desarrollo de defectos congénitos graves. El riesgo disminuye conforme avanza la edad gestacional.\n🔑 CONCEPTOS CLAVERiesgo estimado de defectos congénitos:\nAntes de 11 semanas: aproximadamente 90%.\n11-12 semanas: 33%.\n13-14 semanas: 11%.\n15-16 semanas: 24%.\nDespués de 16 semanas: los defectos congénitos son poco frecuentes, aunque puede producirse infección fetal.\nLa infección congénita ocurre durante la viremia materna, con propagación transplacentaria.\n⚡ REPASO ACTIVORubéola en embarazo: cuanto más precoz la infección, mayor riesgo fetal.\nPerla CONAREM: primeras 8 semanas = máximo riesgo de malformaciones graves.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, pág. 1965.",
