    "correctOptionIndex": 4,
    "explanation": "Respuesta correcta: Leucopenia, neutropenia y trombocitopenia leve\n🧠 ANÁLISIS DE LA PREGUNTALa rubéola no complicada puede acompañarse de leucopenia, neutropenia y trombocitopenia leve.\n🔑 CONCEPTOS CLAVEEl diagnóstico específico es importante para:\nVigilancia epidemiológica.\nConfirmación de infección durante el embarazo.\nConfirmación del diagnóstico de rubéola congénita.\nLa prueba serológica más utilizada es:\nIgM específica contra rubéola, que típicamente está presente 4 días después de la aparición del exantema.\nLas pruebas deben interpretarse considerando el contexto clínico y epidemiológico.\n⚡ REPASO ACTIVORubéola no complicada → leucopenia + neutropenia + trombocitopenia leve.\nPara examen, asocia exantema de 3 días + adenopatías retroauriculares/suboccipitales + leucopenia con rubéola.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, pág. 1966.",
