    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: 16-18 días\n🧠 ANÁLISIS DE LA PREGUNTAEl período de incubación de la rubéola es habitualmente de 16-18 días. Posteriormente puede aparecer un pródromo leve seguido de linfadenopatía y exantema.\n🔑 CONCEPTOS CLAVE\nIncubación: 16-18 días.\nLa infección posnatal suele ser leve.\nEn niños, el pródromo suele ser ausente o leve.\nLas adenopatías características son retroauriculares, suboccipitales y cervicales posteriores.\nEl exantema comienza en cara y cuello, se extiende rápidamente al resto del cuerpo y suele desaparecer hacia el tercer día.\nEntre 25-40% de los niños pueden no presentar exantema.\n⚡ REPASO ACTIVORubéola → incubación 16-18 días.Sarampión → incubación 8-12 días.\nEsta diferencia es útil para preguntas comparativas de CONAREM.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, págs. 1965-1966.",
