    "explanation": "Respuesta correcta: Trombocitopenia posinfecciosa\n🧠 ANÁLISIS DE LA PREGUNTALa trombocitopenia posinfecciosa es la complicación más frecuente de la rubéola posnatal. Se presenta aproximadamente en 1 de cada 3.000 casos y ocurre con mayor frecuencia en niños y niñas.\n🔑 CONCEPTOS CLAVE\nTrombocitopenia posinfecciosa: aproximadamente 1/3.000 casos.\nSuele aparecer alrededor de 2 semanas después del inicio del exantema.\nPuede manifestarse con:\nPetequias.\nEpistaxis.\nSangrado gastrointestinal.\nHematuria.\nHabitualmente es autolimitada.\nLa artritis posterior a rubéola es más frecuente en adultos, especialmente mujeres.\n⚡ REPASO ACTIVORubéola + complicación más frecuente → trombocitopenia posinfecciosa.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, pág. 1967.",
