    "correctOptionIndex": 4,
    "explanation": "Respuesta correcta: No debe administrarse durante el embarazo\n🧠 ANÁLISIS DE LA PREGUNTALa vacuna contra la rubéola contiene virus vivos atenuados y no debe administrarse durante el embarazo. Las mujeres deben evitar quedar embarazadas durante los 28 días posteriores a la vacunación.\n🔑 CONCEPTOS CLAVE\nVacuna de virus vivos atenuados.\nEsquema descrito:\nPrimera dosis: 12-15 meses.\nSegunda dosis: 4-6 años.\nNo administrar durante el embarazo.\nEvitar embarazo durante 28 días después de la vacunación.\nLa fiebre leve no es una contraindicación.\nLa vacunación puede considerarse en pacientes con VIH que no estén gravemente inmunocomprometidos.\nLa inmunoglobulina puede interferir con la respuesta inmunitaria a la vacuna.\n⚡ REPASO ACTIVORubéola = vacuna viva → embarazo NO.Después de vacunar → evitar embarazo 28 días.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, pág. 1968.",
