    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Crisis aplásica transitoria con reticulocitopenia marcada\n🧠 ¿POR QUÉ ES LA CORRECTA?\nLos pacientes con anemia hemolítica crónica y elevado recambio eritrocitario son especialmente sensibles a la interrupción de la eritropoyesis causada por parvovirus B19.\nPuede producirse una detención transitoria de la producción eritrocitaria, con caída brusca de la hemoglobina y un recuento de reticulocitos que puede llegar a ser indetectable.\n📚 CONCEPTOS CLAVE\nMayor riesgo en pacientes con anemia hemolítica crónica.\nComplicación característica → crisis aplásica transitoria.\nHallazgo clave → reticulocitopenia intensa.\nPuede existir una caída marcada de la hemoglobina.\nLa recuperación se acompaña de reticulocitosis y aumento de la hemoglobina.\n⚡ CLAVE CONAREM\nAnemia hemolítica + B19 + caída de Hb + reticulocitos bajos = crisis aplásica transitoria.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, pág. 1988.",
