    "explanation": "Respuesta correcta: Compromete característicamente las palmas y plantas durante la segunda fase.\n🧠 ¿POR QUÉ ES LA CORRECTA?\nEl exantema característico comienza con eritema facial intenso, dando la apariencia de “mejillas abofeteadas”. Posteriormente se extiende al tronco y extremidades proximales y desarrolla un patrón reticulado o en encaje.\nLas lesiones tienden a predominar sobre superficies extensoras y no aparecen en las palmas ni en las plantas.\n📚 CONCEPTOS CLAVE\nPrimera fase → mejillas abofeteadas.\nSegunda fase → tronco y extremidades proximales.\nPatrón → reticulado/en encaje.\nPredominio → superficies extensoras.\nRespeta palmas y plantas.\nPuede fluctuar durante 1–3 semanas.\nPuede reaparecer con sol, calor, ejercicio y estrés.\n⚡ CLAVE CONAREM\nMejillas abofeteadas + exantema reticulado + respeto palmoplantar = eritema infeccioso.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, pág. 1988.",
