    "options": [
      "Eritrocitosis fetal persistente",
      "Hidropesía fetal no inmunitaria",
      "Macrosomía fetal aislada",
      "Policitemia neonatal fisiológica",
      "Malformaciones congénitas teratogénicas características"
    ],
    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Hidropesía fetal no inmunitaria\n🧠 ¿POR QUÉ ES LA CORRECTA?\nEl parvovirus B19 puede atravesar la placenta e infectar al feto. Su efecto citopático sobre los precursores eritroides puede ocasionar anemia fetal profunda, seguida de insuficiencia cardíaca de alto gasto e hidropesía fetal.\nLa infección materna por parvovirus B19 no se considera teratogénica.\n📚 CONCEPTOS CLAVE\nB19 puede atravesar la placenta.\nPuede producir anemia fetal grave.\nComplicación característica → hidropesía fetal no inmunitaria.\nPuede producir insuficiencia cardíaca fetal de alto gasto.\nLa infección fetal puede aparecer desde aproximadamente las 6 semanas de gestación.\nEl parvovirus B19 no parece ser teratogénico.\n⚡ CLAVE CONAREM\nEmbarazada + parvovirus B19 → anemia fetal → hidropesía fetal no inmunitaria.\nNo confundir toxicidad fetal con teratogenicidad.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, pág. 1988.",
