    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: 10 a 21 días\n🧠 ANÁLISIS DE LA PREGUNTALa varicela suele comenzar 14-16 días después de la exposición, aunque el período de incubación puede variar entre 10 y 21 días.\n🔑 CONCEPTOS CLAVE\nIncubación: 10-21 días.\nInicio habitual: 14-16 días después de la exposición.\nEl VHS y el VVZ pertenecen al grupo de los herpesvirus.\nLa infección primaria por VVZ produce varicela.\nLa reactivación de la infección latente produce herpes zóster.\n⚡ REPASO ACTIVOExposición → incubación 10-21 días → varicela.El comienzo de la enfermedad ocurre habitualmente a los 14-16 días de la exposición.\n⚡ CLAVE CONAREMVaricela: 10-21 días de incubación; típico 14-16 días.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-Zoster Virus.",
