    "correctOptionIndex": 4,
    "explanation": "Respuesta correcta: La infección primaria por VVZ produce habitualmente herpes zóster.\n🧠 ANÁLISIS DE LA PREGUNTALa infección primaria por VVZ produce varicela. Después de la infección primaria, el virus establece latencia en los ganglios sensitivos; su posterior reactivación produce herpes zóster.\n🔑 CONCEPTOS CLAVE\nVVZ es un herpesvirus humano neurotrópico.\nInfección primaria → varicela.\nLatencia → ganglios sensitivos.\nReactivación → herpes zóster.\nLa inmunidad celular desempeña un papel importante en el control de la infección.\n⚡ REPASO ACTIVOVVZ → infección primaria → varicela → latencia en ganglios sensitivos → reactivación → herpes zóster.\n⚡ CLAVE CONAREMNo confundir: varicela = primoinfección; zóster = reactivación.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-Zoster Virus.",
