    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Administrar inmunoglobulina varicela-zóster lo antes posible después del nacimiento\n🧠 ANÁLISIS DE LA PREGUNTALos recién nacidos cuyas madres presentan varicela entre 5 días antes y 2 días después del parto deben recibir inmunoglobulina contra varicela-zóster (VZIG) tan pronto como sea posible después del nacimiento.\n🔑 CONCEPTOS CLAVE\nVZIG está indicada en esta situación de alto riesgo.\nPuede no prevenir completamente la infección.\nPuede modificar o disminuir la gravedad de la enfermedad.\nSi VZIG no está disponible, la inmunoglobulina intravenosa puede proporcionar cierta protección.\n⚡ REPASO ACTIVORecién nacido expuesto en período perinatal de alto riesgo:\nMadre con varicela −5 a +2 días → VZIG lo antes posible después del nacimiento.\n⚡ CLAVE CONAREMLa ventana −5/+2 debe asociarse inmediatamente con VZIG neonatal.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-Zoster Virus.",
