    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: Niños inmunocomprometidos con alteración de la inmunidad celular\n🧠 ANÁLISIS DE LA PREGUNTALa varicela progresiva con compromiso visceral es una complicación grave que aparece principalmente en niños inmunocomprometidos, especialmente cuando existe alteración de la inmunidad celular.\n🔑 CONCEPTOS CLAVE\nPuede aparecer después de aproximadamente 7 días.\nSe caracteriza por hemorragia grave, coagulopatía y desarrollo continuo de vesículas.\nPuede producir dolor abdominal intenso por compromiso de ganglios mesentéricos o hígado.\nPuede acompañarse de vesículas hemorrágicas en otros pacientes previamente sanos.\n⚡ REPASO ACTIVOGrupos de alto riesgo mencionados: niños con trastornos congénitos de inmunidad celular, enfermedades malignas, especialmente con quimioterapia, y pacientes que reciben corticoides en dosis altas.\n⚡ CLAVE CONAREMVaricela + inmunodeficiencia celular = riesgo de enfermedad progresiva/diseminada grave.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-Zoster Virus.",
