    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: Herpes zóster\n🧠 ANÁLISIS DE LA PREGUNTAEl herpes zóster se manifiesta mediante vesículas agrupadas dentro de uno o, con menor frecuencia, dos dermatomas adyacentes. Habitualmente comienza con dolor urente o prurito seguido de lesiones cutáneas de distribución dermatomérica.\n🔑 CONCEPTOS CLAVE\nRepresenta la reactivación del VVZ latente.\nLas lesiones siguen una distribución dermatomérica.\nPuede existir dolor urente o prurito antes de las lesiones.\nEn niños suele ser menos grave que en adultos.\nLa neuralgia posherpética es mucho menos frecuente en niños.\n⚡ REPASO ACTIVOEn niños: dolor/prurito → vesículas agrupadas en dermatoma → nuevas lesiones durante algunos días → resolución completa habitualmente en 1-2 semanas.\n⚡ CLAVE CONAREMVesículas unilaterales + dermatoma = herpes zóster.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-Zoster Virus.",
