    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: La neuralgia posherpética es mucho menos frecuente que en los adultos.\n🧠 ANÁLISIS DE LA PREGUNTAEl herpes zóster infantil suele ser menos grave que en adultos, y la neuralgia posherpética es mucho menos frecuente. Además, el VVZ atenuado de la vacuna también puede establecer latencia y posteriormente reactivarse.\n🔑 CONCEPTOS CLAVE\nEn niños suele existir menos dolor localizado.\nLa hiperestesia, prurito y febrícula pueden preceder o acompañar las lesiones.\nLa resolución completa suele producirse en 1-2 semanas.\nLa neuralgia posherpética es infrecuente en la infancia.\n⚡ REPASO ACTIVOEl zóster puede producirse por reactivación de VVZ salvaje o VVZ vacunal atenuado. Los niños inmunocomprometidos pueden presentar formas más graves, enfermedad cutánea diseminada y compromiso visceral.\n⚡ CLAVE CONAREMZóster pediátrico = generalmente más leve + neuralgia posherpética rara.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-Zoster Virus.",
