    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Obstrucción de la vía aérea\n🧠 ANÁLISIS DE LA PREGUNTALas complicaciones graves son infrecuentes en la mononucleosis infecciosa. La obstrucción de la vía aérea por edema del tejido linfático orofaríngeo ocurre en menos del 5% de los casos y constituye una de las complicaciones reconocidas.\n🔑 CONCEPTOS CLAVE\nLas complicaciones graves son inusuales.\nLa obstrucción de la vía aérea ocurre en <5% de los casos.\nSe produce por edema del tejido linfático orofaríngeo.\nLa rotura esplénica puede producirse espontáneamente o después de traumatismos leves, pero es rara.\n⚡ REPASO ACTIVOComplicaciones descritas: rotura esplénica, obstrucción de la vía aérea, meningitis o encefalitis, convulsiones, ataxia, síndrome de Alicia en el País de las Maravillas, mielitis transversa, parálisis, anemia hemolítica, trombocitopenia, neutropenia, anemia aplásica, miocarditis, nefritis intersticial, pancreatitis, parotiditis y orquitis.\n⚡ CLAVE CONAREMMononucleosis + hipertrofia/edema orofaríngeo importante → vigilar obstrucción de la vía aérea.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
