    "explanation": "Respuesta correcta: Puede producirse espontáneamente o después de un traumatismo menor\n🧠 ANÁLISIS DE LA PREGUNTALa rotura esplénica es una complicación rara, pero puede producirse espontáneamente o después de un traumatismo menor. El texto señala una frecuencia aproximada de 0,1% de los casos.\n🔑 CONCEPTOS CLAVE\nFrecuencia aproximada: 0,1%.\nPuede ser espontánea.\nUn traumatismo menor puede desencadenarla.\nLa esplenomegalia es frecuente durante la mononucleosis.\n⚡ REPASO ACTIVOLa esplenomegalia ocurre en 50% de los casos de mononucleosis infecciosa. La rotura esplénica es mucho menos frecuente, aproximadamente 0,1%.\n⚡ CLAVE CONAREMEsplenomegalia es frecuente; rotura esplénica es rara pero potencialmente grave.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
