    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Síndrome de Alicia en el País de las Maravillas\n🧠 ANÁLISIS DE LA PREGUNTAEntre las manifestaciones neurológicas graves se describe ataxia, convulsiones y alteraciones de la percepción visual, conocidas como síndrome de Alicia en el País de las Maravillas (metamorfopsia).\n🔑 CONCEPTOS CLAVE\nLa meningitis o encefalitis sintomática es infrecuente.\nPueden presentarse convulsiones.\nPuede aparecer ataxia.\nLa metamorfopsia constituye una manifestación característica descrita.\nTambién pueden presentarse mielitis transversa o parálisis.\n⚡ REPASO ACTIVOComplicaciones neurológicas: meningitis, encefalitis, convulsiones, ataxia, síndrome de Alicia en el País de las Maravillas, mielitis transversa y parálisis.\n⚡ CLAVE CONAREMVEB + alteraciones llamativas de la percepción visual = pensar en síndrome de Alicia en el País de las Maravillas.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
