    "explanation": "Respuesta correcta: Anemia hemolítica leve\n🧠 ANÁLISIS DE LA PREGUNTALas alteraciones hematológicas como anemia hemolítica leve, trombocitopenia y neutropenia son relativamente frecuentes. En cambio, la anemia aplásica y la trombocitopenia grave son poco frecuentes.\n🔑 CONCEPTOS CLAVE\nAnemia hemolítica leve: relativamente frecuente.\nTrombocitopenia: relativamente frecuente.\nNeutropenia: relativamente frecuente.\nAnemia aplásica: rara.\nTrombocitopenia grave: rara.\n⚡ REPASO ACTIVOFrecuentes: anemia hemolítica leve + trombocitopenia + neutropenia.Raras: anemia aplásica + trombocitopenia grave.\n⚡ CLAVE CONAREMEn mononucleosis, las citopenias leves pueden aparecer; las formas hematológicas graves son mucho menos frecuentes.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
