    "explanation": "Respuesta correcta: Pacientes con respuestas inmunitarias desreguladas\n🧠 ANÁLISIS DE LA PREGUNTALos pacientes con respuestas inmunitarias desreguladas frente a la infección primaria, como aquellos con linfohistiocitosis hemofagocítica primaria y trastornos de inmunodeficiencia, presentan mayor riesgo de complicaciones graves.\n🔑 CONCEPTOS CLAVE\nLa inmunodeficiencia puede favorecer manifestaciones graves.\nSe describe asociación con linfohistiocitosis hemofagocítica.\nAlgunos defectos inmunitarios predisponen a proliferación incontrolada de linfocitos B infectados por VEB.\nLas manifestaciones pueden llegar a ser fulminantes.\n⚡ REPASO ACTIVOGrupos señalados: linfohistiocitosis hemofagocítica primaria + trastornos de inmunodeficiencia + otros defectos que alteran el control inmunitario del VEB.\n⚡ CLAVE CONAREMVEB + inmunidad celular alterada/desregulada = mayor riesgo de enfermedad grave.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
