    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Linfohistiocitosis hemofagocítica\n🧠 ANÁLISIS DE LA PREGUNTALa linfohistiocitosis hemofagocítica (LHH) se encuentra entre las complicaciones graves asociadas a una respuesta inmunitaria desregulada frente al VEB.\n🔑 CONCEPTOS CLAVE\nPuede asociarse a infección primaria por VEB.\nLos pacientes afectados tienen mayor riesgo de complicaciones graves.\nDeterminados defectos genéticos predisponen a LHH asociada a VEB.\nLa alteración de la función de linfocitos T y células NK es relevante en estos pacientes.\n⚡ REPASO ACTIVOEntre los defectos mencionados que predisponen a enfermedad grave asociada a VEB se encuentran alteraciones relacionadas con XIAP, SH2D1A, MAGT1, ITK, CD27 y CD70, entre otras.\n⚡ CLAVE CONAREMVEB + respuesta inmunitaria descontrolada + cuadro sistémico grave → pensar en LHH.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
