    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: 30 a 50 días\n🧠 ANÁLISIS DE LA PREGUNTAEl período de incubación de la mononucleosis infecciosa en adolescentes es de 30 a 50 días. En lactantes y niños pequeños, la infección primaria por VEB suele ser clínicamente silenciosa.\n🔑 CONCEPTOS CLAVE\nIncubación en adolescentes: 30-50 días.\nLa mayoría de los casos de infección primaria por VEB en lactantes y niños pequeños son clínicamente silenciosos.\nEn adolescentes y adultos jóvenes, la infección primaria suele manifestarse con la tríada clásica de fatiga, faringitis y linfadenopatía generalizada.\nLa enfermedad en adultos mayores de 40 años puede presentarse de manera atípica.\n⚡ REPASO ACTIVOAdolescentes: incubación 30-50 días → inicio insidioso con malestar, fatiga, cefalea y odinofagia → tríada clásica: fatiga + faringitis + linfadenopatía generalizada.\n⚡ CLAVE CONAREMVEB en adolescente = incubación larga: 30-50 días.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
