    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Petequias\n🧠 ANÁLISIS DE LA PREGUNTAEntre los hallazgos clínicos de los lactantes con infección congénita sintomática, las petequias aparecen en aproximadamente 54%, siendo el hallazgo clínico más frecuente de los enumerados en la tabla.\n🔑 CONCEPTOS CLAVE\nPetequias: 54%.\nMicrocefalia: 35%.\nRestricción del crecimiento intrauterino: 28%.\nPrematuridad (<37 semanas): 24%.\nHepatoesplenomegalia: 19%.\nPúrpura: 3%.\n⚡ REPASO ACTIVOHallazgos clínicos de CMV congénito sintomático:\nPetequias 54% → microcefalia 35% → RCIU 28% → prematuridad 24% → hepatoesplenomegalia 19% → púrpura 3%.\nEl 59% presenta ≥2 hallazgos clínicos y el 41% presenta un solo hallazgo.\n⚡ CLAVE CONAREMEntre los hallazgos clínicos de la tabla: petequias = el más frecuente (54%).\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, pág. 2013, tabla 302.2.",
