    "explanation": "Respuesta correcta: Elevación de ALT\n🧠 ANÁLISIS DE LA PREGUNTALa elevación de ALT >80 UI/mL se observa en aproximadamente 71% de los lactantes con infección congénita sintomática por CMV, siendo el hallazgo de laboratorio más frecuente de la tabla.\n🔑 CONCEPTOS CLAVE\nALT elevada: 71%.\nHiperbilirrubinemia directa: 54%.\nTrombocitopenia: 43%.\nAlteraciones en TC de cráneo: 42%.\n⚡ REPASO ACTIVOHallazgos de laboratorio:\nALT elevada 71% → hiperbilirrubinemia directa 54% → trombocitopenia 43% → anomalías en TC cerebral 42%.\n⚡ CLAVE CONAREMCMV congénito sintomático: hallazgo clínico frecuente = petequias; laboratorio más frecuente = ALT elevada.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, pág. 2013, tabla 302.2.",
