    "id": "semana17_ped_q112",
    "text": "¿Cuál es la evolución clínica característica de la roséola infantil?",
    "options": [
      "Exantema vesicular seguido de fiebre persistente durante una semana",
      "Fiebre alta seguida de exantema al disminuir bruscamente la temperatura",
      "Exantema pruriginoso acompañado de fiebre durante toda la enfermedad",
      "Fiebre moderada seguida de lesiones vesiculares de distribución acral",
      "Exantema petequial previo al desarrollo de fiebre elevada persistente"
    ],
    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Fiebre alta seguida de exantema al disminuir bruscamente la temperatura\n🧠 ANÁLISIS DE LA PREGUNTALa roséola comienza característicamente con fiebre alta de aparición brusca. La fiebre suele persistir 3-5 días y posteriormente disminuye de manera rápida; coincidiendo con esta defervescencia aparece el exantema.\n🔑 CONCEPTOS CLAVE\nInicio brusco con fiebre elevada.\nTemperatura media máxima: 39,7 °C.\nLa fiebre persiste habitualmente 3-5 días.\nEl exantema aparece con la rápida disminución de la temperatura.\nLa erupción suele comenzar en el tronco.\n⚡ REPASO ACTIVOSecuencia clásica:\nFiebre alta brusca → 3-5 días → defervescencia rápida → exantema maculopapular rosado → inicia en tronco → se extiende a cara y extremidades.\n⚡ CLAVE CONAREMRoséola = primero fiebre, después exantema. El dato clave es que el niño desarrolla el rash cuando cede la fiebre.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 303, Roseola (Human Herpesviruses 6 and 7), págs. 2016-2017.",
