    "id": "semana17_ped_q118",
    "text": "¿Cuál de los siguientes criterios clínicos permite diagnosticar sinusitis bacteriana aguda en un niño?",
    "options": [
      "Congestión nasal y tos durante 5 días con mejoría progresiva",
      "Rinorrea purulenta aislada durante 3 días sin fiebre",
      "Síntomas respiratorios persistentes durante más de 10 días sin mejoría",
      "Tos nocturna durante 7 días asociada a rinorrea acuosa",
      "Obstrucción nasal durante 4 días acompañada de cefalea leve"
    ],
    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: Síntomas respiratorios persistentes durante más de 10 días sin mejoría\n🧠 ANÁLISIS DE LA PREGUNTAEl diagnóstico clínico de sinusitis bacteriana aguda puede establecerse cuando los síntomas de infección de vías respiratorias superiores, incluyendo secreción nasal y/o tos diurna, persisten durante más de 10 días sin mejoría.\n🔑 CONCEPTOS CLAVEEl texto establece tres presentaciones diagnósticas:\nEnfermedad persistente: secreción nasal y/o tos diurna >10 días sin mejoría.\nEmpeoramiento o “doble empeoramiento”: nueva secreción nasal, tos diurna o fiebre después de una mejoría inicial.\nInicio grave: temperatura ≥39 °C y secreción nasal purulenta durante 3-4 días consecutivos.\n⚡ REPASO ACTIVOEl diagnóstico de sinusitis bacteriana aguda es fundamentalmente clínico. Los hallazgos radiológicos como opacificación, engrosamiento mucoso o nivel hidroaéreo no son diagnósticos y no se recomiendan de rutina en niños por lo demás sanos.\n⚡ CLAVE CONAREMSinusitis bacteriana = >10 días sin mejorar, doble empeoramiento o inicio grave.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2555.",
