    "id": "semana17_ped_q120",
    "text": "¿Cuáles son los microorganismos bacterianos más frecuentes en la sinusitis bacteriana aguda en niños y adolescentes?",
    "options": [
      "Staphylococcus aureus, Pseudomonas aeruginosa y anaerobios",
      "Streptococcus pneumoniae, Haemophilus influenzae no tipificable y Moraxella catarrhalis",
      "Streptococcus pyogenes, Staphylococcus aureus y Moraxella catarrhalis",
      "Haemophilus influenzae tipo b, Streptococcus pyogenes y anaerobios",
      "Pseudomonas aeruginosa, Streptococcus pneumoniae y Staphylococcus aureus"
    ],
    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Streptococcus pneumoniae, Haemophilus influenzae no tipificable y Moraxella catarrhalis\n🧠 ANÁLISIS DE LA PREGUNTALos principales patógenos bacterianos de la sinusitis bacteriana aguda pediátrica son S. pneumoniae (~30%), H. influenzae no tipificable (~50%) y M. catarrhalis (~10%).\n🔑 CONCEPTOS CLAVE\nH. influenzae no tipificable: aproximadamente 50%.\nS. pneumoniae: aproximadamente 30%.\nM. catarrhalis: aproximadamente 10%.\nCerca del 50% de H. influenzae y el 100% de M. catarrhalis producen β-lactamasa.\n⚡ REPASO ACTIVOS. aureus, otros estreptococos y anaerobios son causas poco frecuentes de sinusitis bacteriana aguda en niños. En la sinusitis crónica pueden recuperarse con mayor frecuencia otros microorganismos.\n⚡ CLAVE CONAREMTrío bacteriano pediátrico: H. influenzae + neumococo + Moraxella.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2554.",
