    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Amoxicilina-clavulanato 45 mg/kg/día por vía oral\n🧠 ANÁLISIS DE LA PREGUNTASegún la tabla del capítulo, el tratamiento empírico inicial para enfermedad leve a moderada es amoxicilina-clavulanato 45 mg/kg/día, dividido en dos dosis, durante 10 días.\n🔑 CONCEPTOS CLAVE\nLeve-moderada: amoxicilina-clavulanato 45 mg/kg/día VO, dividido cada 12 h.\nEmpeoramiento agudo o enfermedad grave: amoxicilina-clavulanato 90 mg/kg/día VO, dividido cada 12 h.\nHipersensibilidad tipo I a β-lactámicos: levofloxacino.\nHipersensibilidad no tipo I: cefpodoxima.\nInfección grave que requiere hospitalización: tratamiento intravenoso.\n⚡ REPASO ACTIVOEn niños hospitalizados con enfermedad grave, las opciones descritas incluyen ampicilina-sulbactam, ceftriaxona o levofloxacino IV.\n⚡ CLAVE CONAREMSinusitis bacteriana leve-moderada → amoxicilina-clavulanato 45 mg/kg/día.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2556, tabla 429.2.",
