    "explanation": "Respuesta correcta: La celulitis periorbitaria produce característicamente disminución de la agudeza visual y diplopía\n🧠 ANÁLISIS DE LA PREGUNTALa celulitis periorbitaria produce principalmente eritema y edema de los tejidos que rodean el globo ocular. En cambio, la celulitis orbitaria afecta las estructuras intraorbitarias y puede ocasionar proptosis, quemosis, disminución de la agudeza visual, diplopía, alteración de los movimientos extraoculares y dolor ocular.\n🔑 CONCEPTOS CLAVEComplicaciones orbitarias:\nCelulitis periorbitaria.\nCelulitis orbitaria.\nComplicaciones intracraneales:\nAbsceso epidural.\nMeningitis.\nTrombosis del seno cavernoso.\nEmpiema subdural.\nAbsceso cerebral.\n⚡ REPASO ACTIVOPeriorbitaria: eritema + edema alrededor del ojo.Orbitaria: proptosis + quemosis + ↓ agudeza visual + diplopía + alteración de movimientos extraoculares + dolor ocular.\nSignos de alarma intracraneal: alteración del estado mental, rigidez de nuca, déficit neurológico focal, convulsiones o aumento de presión intracraneal.\n⚡ CLAVE CONAREMProptosis/diplopía/alteración de movimientos oculares = compromiso orbitario, no simple celulitis periorbitaria.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2556.",
