    "explanation": "Respuesta correcta: 2-5 días\n🧠 ANÁLISIS DE LA PREGUNTADespués de un período de incubación de 2-5 días, la infección faríngea por estreptococo del grupo A suele manifestarse con inicio rápido de odinofagia significativa y fiebre.\n🔑 CONCEPTOS CLAVE\nIncubación: 2-5 días.\nInicio habitualmente rápido.\nOdinofagia y fiebre son manifestaciones características.\nEs relativamente infrecuente antes de los 2-3 años.\nEs frecuente entre los 5-15 años.\n⚡ REPASO ACTIVOLa faringitis estreptocócica ocurre durante todo el año, pero es más frecuente en invierno y primavera. Se disemina fácilmente entre hermanos y compañeros escolares y representa aproximadamente 15-30% de las faringitis en niños en edad escolar.\n⚡ CLAVE CONAREMEstreptococo del grupo A → incubación 2-5 días + inicio brusco.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, pág. 2559.",
