    "correctOptionIndex": 4,
    "explanation": "Respuesta correcta: Conjuntivitis\n🧠 ANÁLISIS DE LA PREGUNTALa conjuntivitis es un hallazgo que orienta hacia etiología viral. El texto señala que diarrea, tos, coriza, ulceraciones, crup/laringitis/ronquera y conjuntivitis no se asocian con faringitis estreptocócica y aumentan la probabilidad de etiología viral.\n🔑 CONCEPTOS CLAVE\nSugieren estreptococo del grupo A:\nInicio brusco de odinofagia.\nEdad 5-15 años.\nFiebre.\nCefalea.\nNáuseas, vómitos o dolor abdominal.\nInflamación amigdalofaríngea.\nExudado amigdalino parcheado.\nPetequias palatinas.\nAdenopatía cervical anterior dolorosa.\nAusencia de tos o coriza.\nSugieren etiología viral:\nConjuntivitis.\nCoriza.\nTos.\nDiarrea.\nRonquera.\nEstomatitis ulcerativa.\nExantema viral.\n⚡ REPASO ACTIVOLa clínica estreptocócica y viral puede superponerse; los hallazgos clínicos por sí solos pueden sobreestimar la probabilidad de etiología estreptocócica.\n⚡ CLAVE CONAREMTos + coriza + conjuntivitis + ronquera + diarrea → pensar VIRAL.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, págs. 2558-2559, tabla 430.2.",
