    "explanation": "Respuesta correcta: Estreptococo del grupo A\n🧠 ANÁLISIS DE LA PREGUNTAEl cuadro reúne múltiples características que orientan a faringitis por estreptococo del grupo A: edad de 5-15 años, inicio brusco, fiebre, inflamación y exudado amigdalino, petequias palatinas, adenopatías cervicales anteriores dolorosas y ausencia de tos.\n🔑 CONCEPTOS CLAVE\nGrupo etario característico: 5-15 años.\nFaringe eritematosa.\nAmígdalas aumentadas y frecuentemente cubiertas por exudado.\nPuede haber petequias en paladar blando y faringe posterior.\nAdenopatías cervicales anteriores aumentadas y dolorosas son frecuentes.\n⚡ REPASO ACTIVOOtros síntomas asociados incluyen cefalea, dolor abdominal, náuseas y vómitos. En ausencia de faringitis clínica, los síntomas gastrointestinales no deben atribuirse al estreptococo.\n⚡ CLAVE CONAREMEscolar + fiebre + exudado + adenopatía cervical anterior dolorosa + NO tos = estreptococo del grupo A.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, pág. 2559.",
