    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Una prueba rápida negativa no requiere confirmación mediante cultivo faríngeo\n🧠 ANÁLISIS DE LA PREGUNTALa afirmación es incorrecta. Debido a que las pruebas rápidas de detección de antígeno son generalmente menos sensibles que el cultivo, el texto indica que se recomienda un cultivo faríngeo confirmatorio cuando la prueba rápida es negativa.\n🔑 CONCEPTOS CLAVE\nCultivo faríngeo: estándar de referencia.\nPrueba rápida de antígeno: especificidad generalmente ≥95%.\nPrueba rápida positiva: se considera precisa.\nPrueba rápida negativa: confirmar con cultivo faríngeo.\nPruebas moleculares: sensibilidad y especificidad reportadas >98% frente al cultivo estándar.\n⚡ REPASO ACTIVOLas pruebas deben utilizarse según la probabilidad clínica. El texto recomienda evitar pruebas cuando los signos y síntomas sugieren fuertemente una infección viral.\n⚡ CLAVE CONAREMPrueba rápida positiva → aceptar. Negativa → cultivo confirmatorio.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, págs. 2559-2560.",
