    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Prevenir la fiebre reumática aguda\n🧠 ANÁLISIS DE LA PREGUNTAEl texto establece que el principal beneficio y objetivo del tratamiento antibiótico es la prevención de la fiebre reumática aguda. Esto sigue siendo efectivo cuando el tratamiento comienza dentro de los 10 días desde el inicio de la enfermedad.\n🔑 CONCEPTOS CLAVE\nEl tratamiento acorta la recuperación clínica en aproximadamente 12-24 horas.\nReduce las complicaciones supurativas.\nEl principal objetivo es prevenir la fiebre reumática aguda.\nPuede prevenirse incluso iniciando tratamiento dentro de los primeros 10 días.\nEl tratamiento antibiótico no previene la glomerulonefritis postestreptocócica aguda.\n⚡ REPASO ACTIVOComplicaciones supurativas mencionadas: absceso periamigdalino y adenitis cervical. El beneficio preventivo fundamental del antibiótico sigue siendo la prevención de fiebre reumática aguda.\n⚡ CLAVE CONAREMAntibiótico en faringitis estreptocócica → previene fiebre reumática, NO glomerulonefritis postestreptocócica.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, pág. 2560.",
