    "explanation": "Respuesta correcta: Habitualmente requiere tratamiento antibiótico para erradicar el microorganismo\n🧠 ANÁLISIS DE LA PREGUNTAEl texto señala que generalmente no es necesario intentar eliminar el estado de portador crónico. Si un niño colonizado desarrolla una faringitis viral, la prueba para estreptococo puede resultar positiva y generar confusión diagnóstica.\n🔑 CONCEPTOS CLAVE\nEl portador puede continuar albergando estreptococo pese a tratamiento adecuado.\nPresenta poca o ninguna respuesta inflamatoria.\nEl estado de portador suele representar poco riesgo.\nNo se recomienda tratar rutinariamente el estado de portador.\nUna prueba positiva no demuestra necesariamente que el estreptococo sea la causa del episodio actual.\n⚡ REPASO ACTIVOLa evaluación de una nueva faringitis debe realizarse sin asumir automáticamente que se trata de estreptococo por el antecedente de portación crónica. El objetivo es evitar pruebas y antibióticos innecesarios.\n⚡ CLAVE CONAREMPortador + cuadro viral + prueba positiva ≠ necesariamente faringitis estreptocócica activa.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, pág. 2561.",
