    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Chlamydophila psittaci\n🧠 ANÁLISIS DE LA PREGUNTAChlamydophila psittaci presenta una asociación característica con contacto con aves, especialmente periquitos.\n🔑 CONCEPTOS CLAVE\nC. psittaci → aves, especialmente periquitos.\nC. burnetii → cabras, ovejas y ganado.\nY. pestis → ratas.\nF. tularensis → animales, garrapatas y moscas.\n⚡ REPASO ACTIVOLas exposiciones animales permiten orientar la etiología: aves con C. psittaci, ratas con Y. pestis, animales/garrapatas/moscas con F. tularensis y cabras/ovejas/ganado con C. burnetii.\n⚡ CLAVE CONAREMAves, especialmente periquitos → Chlamydophila psittaci.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
