    "correctOptionIndex": 4,
    "explanation": "Respuesta correcta: Virus respiratorio sincitial\n🧠 ANÁLISIS DE LA PREGUNTAEl virus respiratorio sincitial se relaciona característicamente con bronquiolitis. Los virus parainfluenza 1-4 se asocian con crup.\n🔑 CONCEPTOS CLAVE\nVirus respiratorio sincitial → bronquiolitis.\nParainfluenza 1-4 → crup.\nInfluenza A y B → fiebre alta y meses de invierno.\nRinovirus → rinorrea.\n⚡ REPASO ACTIVOLas causas virales comunes incluyen virus respiratorio sincitial, parainfluenza 1-4, influenza A/B, adenovirus, metapneumovirus humano y SARS-CoV-2.\n⚡ CLAVE CONAREMBronquiolitis → virus respiratorio sincitial. Crup → parainfluenza.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
