    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Influenza A e influenza B\n🧠 ANÁLISIS DE LA PREGUNTALos virus influenza A y B se relacionan con fiebre alta y predominio durante los meses de invierno.\n🔑 CONCEPTOS CLAVE\nInfluenza A/B → fiebre alta e invierno.\nAdenovirus → puede ser grave; enero a abril.\nRinovirus → rinorrea.\nParainfluenza → crup.\n⚡ REPASO ACTIVOLos virus poco comunes incluyen rinovirus, enterovirus D68, herpes simple, citomegalovirus, sarampión, varicela, hantavirus y coronavirus SARS-CoV-1/MERS.\n⚡ CLAVE CONAREMFiebre alta + invierno → influenza A/B.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
