    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Anaerobios mixtos\n🧠 ANÁLISIS DE LA PREGUNTALos anaerobios mixtos se asocian con neumonía por aspiración.\n🔑 CONCEPTOS CLAVE\nAnaerobios mixtos → neumonía por aspiración.\nEnterobacterias gramnegativas → neumonía nosocomial.\nChlamydia trachomatis → lactantes.\n⚡ REPASO ACTIVOAsociaciones bacterianas importantes:\nStreptococcus pneumoniae → consolidación, empiema.\nEstreptococo del grupo B → neonatos.\nEstreptococo del grupo A → empiema.\nStaphylococcus aureus → neumatoceles, empiema; lactantes; neumonía nosocomial.\nMycoplasma pneumoniae → adolescentes; epidemias de verano a otoño.\nChlamydophila pneumoniae → adolescentes.\nChlamydia trachomatis → lactantes.\nAnaerobios mixtos → neumonía por aspiración.\nEnterobacterias gramnegativas → neumonía nosocomial.\n⚡ CLAVE CONAREMAspiración → anaerobios mixtos.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
