    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: Rodilla\n🧠 ANÁLISIS DE LA PREGUNTALa rodilla constituye la localización más frecuente de la artritis bacteriana hematógena, representando aproximadamente 35% de los casos. La cadera ocupa el segundo lugar, con aproximadamente 25%.\n🔑 CONCEPTOS CLAVE\nRodilla → ≈35%.\nCadera → ≈25%.\nTobillo → ≈10%.\nCodo → ≈10%.\nHombro → ≈5%.\n⚡ REPASO ACTIVO — DISTRIBUCIÓN COMPLETA\nRodilla: ≈35%.\nCadera: ≈25%.\nTobillo: ≈10%.\nCodo: ≈10%.\nHombro: ≈5%.\nMuñeca: ≈4%.\nArticulaciones pequeñas: ≈1-2%.\nEsta distribución corresponde a artritis bacteriana hematógena y excluye la enfermedad de Lyme y la artritis postinfecciosa por complejos inmunes.\n⚡ CLAVE CONAREMArtritis séptica hematógena → rodilla primero (35%), cadera segundo (25%).\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726, tabla 726.1.",
