    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Rodilla 35%, cadera 25% y tobillo 10%\n🧠 ANÁLISIS DE LA PREGUNTALa frecuencia disminuye desde la rodilla (≈35%), seguida por la cadera (≈25%) y posteriormente el tobillo (≈10%).\n🔑 CONCEPTOS CLAVE\nRodilla → localización más frecuente.\nCadera → segunda localización.\nTobillo y codo → aproximadamente 10% cada uno.\nLas articulaciones pequeñas son las menos frecuentes.\n⚡ REPASO ACTIVO — DISTRIBUCIÓN COMPLETAOrden de frecuencia:\nRodilla ≈35% → Cadera ≈25% → Tobillo ≈10% = Codo ≈10% → Hombro ≈5% → Muñeca ≈4% → Articulaciones pequeñas ≈1-2%.\nSe excluyen de esta distribución la enfermedad de Lyme y la artritis postinfecciosa mediada por complejos inmunes.\n⚡ CLAVE CONAREM35-25-10-10: rodilla → cadera → tobillo/codo.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726, tabla 726.1.",
