    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: Artritis de Lyme\n🧠 ANÁLISIS DE LA PREGUNTAEn la artritis de Lyme, la tumefacción articular puede ser muy prominente y desproporcionada respecto al dolor y a la limitación del rango de movimiento, en comparación con una artritis supurativa.\n🔑 CONCEPTOS CLAVE\nTumefacción importante.\nDolor relativamente menor.\nLimitación de movimiento relativamente menor.\nPredilección por grandes articulaciones.\nRodillas y caderas → localizaciones principales.\nPuede ser monoarticular o pauciarticular.\n⚡ REPASO ACTIVO — LYME\nPredilección por grandes articulaciones.\nEspecialmente rodillas y caderas.\nPresentación monoarticular o pauciarticular.\nTumefacción llamativa.\nDolor y limitación proporcionalmente menores que en artritis supurativa.\n⚡ CLAVE CONAREMArticulación muy hinchada pero relativamente poco dolorosa → Lyme.\n📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726.",
