    "id": "semana17_ped_q201",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Sección II: Fases de la enfermedad (Figura 1: Fases de la Enfermedad).\nEn relación con los problemas clínicos característicos asociados a cada una de las fases evolutivas del dengue (febrero, crítica y de recuperación), señale la afirmación INCORRECTA :",
    "options": [
      "Durante la fase crítica, el choque secundario a la extravasación plasmática constituye uno de los eventos principales.",
      "En la fase febril, la deshidratación y las convulsiones asociadas a fiebre alta en niños pequeños son problemas clínicos relevantes.",
      "En la fase de recuperación, el compromiso grave de órganos y las hemorragias graves representan la complicación fisiopatológica central.",
      "A lo largo de la fase crítica, pueden presentarse hemorragias graves y compromiso severo de distintos órganos diana.",
      "La hipervolemia en la fase de recuperación se asocia a la fluidoterapia intravenosa excesiva o indebidamente prolongada."
    ],
    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«En la fase de recuperación, el compromiso grave de órganos y las hemorragias graves representan la complicación fisiopatológica central» es incorrecta porque el choque por extravasación de plasma, las hemorragias graves y el compromiso grave de órganos corresponden exclusivamente a los problemas clínicos de la fase crítica ; El problema clínico predominante de la fase de recuperación es la hipervolemia por exceso o prolongación de fluidos intravenosos.\n🔑 CONCEPTOS CLAVE\nFase febrero: El foco clínico está en el manejo de la deshidratación y en la vigilancia de complicaciones neurológicas/convulsiones febriles en población pediátrica.\nFase Crítica: Concentra las manifestaciones potencialmente mortales: choque hipovolémico por fuga plasmática, hemorragias severas y falla orgánica.\nFase de Recuperación: El principal riesgo iatrogénico y hemodinámico es la sobrecarga hídrica (hipervolemia).\n⚡ REPASO ACTIVO\nTabla 1. Fases del dengue y problemas clínicos asociados:\nFase febrero: Deshidratación ; la fiebre alta puede asociarse a trastornos neurológicos y convulsiones en los niños pequeños.\nFase Crítica: Choque por la extravasación de plasma; hemorragias graves, compromiso serio de órganos.\nFase de recuperaciónRación: Hipervolemia (si la terapia intravenosa de fluidos ha sido excesiva o se ha extendido en este período).\n📖 Referencia:",
