    "id": "semana17_ped_q202",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Tabla 1: Fases febril, crítica y de recuperación del dengue. Problemas clínicos.\nEn la clasificación revisada del dengue, ¿cuál de los siguientes criterios clasifica a un paciente en la categoría de Dengue Grave ?",
    "options": [
      "Dolor abdominal intenso y continuo acompañado de vómitos persistentes.",
      "Hepatomegalia mayor de 2 cm con acumulación clínica de líquidos.",
      "Sangrado de mucosas junto con aumento de hematocrito y caída rápida de plaquetas.",
      "Daño hepático manifestado por niveles de AST o ALT mayores o iguales a 1.000 UI/L.",
      "Fiebre de inicio brusco con exantema, leucopenia y prueba del torniquete positiva."
    ],
    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Daño hepático manifestado por niveles de AST o ALT mayores o iguales a 1.000 UI/L» es la correcta porque el compromiso de daño orgánico grave en hígado con transaminasas (AST o ALT)$\\ge$1.000 UI/L constituye un criterio definitorio de Dengue Grave . Las demás alternativas corresponden a signos de alarma , mientras que «Fiebre de inicio brusco con exantema, leucopenia y prueba del torniquete positiva» describe la definición de caso de dengue sin signos de alarma .\n🔑 CONCEPTOS CLAVE\nEstudio DENCO: Base utilizada por la OMS para clasificar la enfermedad según datos clínicos de severidad y optimizar las decisiones terapéuticas.\nSignos de alarma: Indican el momento de transición hacia las formas graves de la enfermedad y exigen observación estricta e intervención médica.\nCriterios de Dengue Grave: Se divide en tres ejes principales: escape importante de plasma (con choque o acumulación de fluidos con disnea), sangrado grave y daño orgánico grave (hígado, SNC, corazón y otros órganos).\n⚡ REPASO ACTIVO\nDengue sin signos de alarma:\nVive o viajó a áreas endémicas de dengue.\nFiebre y 2 o más manifestaciones: náuseas/vómitos, exantema, mialgias/artralgias, petequias o prueba del torniquete positivo, leucopenia. (Confirmado por laboratorio si no hay escape plasmático).\nDengue con signos de alarma (requiere observación estricta e intervención):\nDolor abdominal intenso y continuo.\nVómito persistente.\nAcumulación de líquidos.\nSangrado de mucosas.\nLetargia / irritabilidad.\nHepatomegalia mayor de 2 cm.\nLaboratorio: Aumento del hematocrito junto con rápida caída de las plaquetas.\nTumba por dengue:\nEscape importante de plasma: choque (SCD) o acumulación de fluidos en pulmón y disnea.\nSangrado tumba: según evaluación del clínico.\nDaño orgánico tumba: Hígado (AST o ALT$\\ge$1.000), SNC (alteraciones sensitivas/conciencia), corazón y otros órganos.\n📖 Referencia:",
