    "id": "semana17_ped_q203",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Sección III: Clasificación Revisada del Dengue (Figura 2: Diagrama de clasificación de dengue).\n¿Cuál de los siguientes hallazgos clínicos o laboratorios corresponden a un signo de alarma en la clasificación revisada del dengue (estudio DENCO/OMS)?",
    "options": [
      "Recuento de leucocitos disminuidos (leucopenia) en el hemograma",
      "Aumento del hematocrito junto con rápida caída de las plaquetas",
      "Transaminasas séricas (AST o ALT) con valores mayores o iguales a 1.000 UI/L",
      "Síndrome de choque por dengue con acumulación de fluidos en pulmón y disnea",
      "Exantema pruriginoso acompañado de mialgias y prueba del torniquete positiva"
    ],
    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Aumento del hematocrito junto con rápida caída de las plaquetas» es la correcta porque el aumento progresivo del hematocrito asociado a un descenso rápido del recuento plaquetario representa el criterio laboratorial establecido específicamente dentro del grupo de signos de alarma , marcando el inicio del escape plasmático y la necesidad de observación estricta e intervención médica.\n🔑 CONCEPTOS CLAVE\nSignos de alarma laboratoriales: El binomio hematocrito elevado + plaquetopenia rápida es el parámetro analítico que define alarma; la leucopenia aislada pertenece a la definición de dengue sin signos de alarma.\nPunto de corte hepático para gravedad: AST o ALT$\\ge$1.000 UI/L clasifica al paciente directamente como Dengue Grave (daño orgánico grave), no como mero signo de alarma.\nSignos de alarma clínica: Dolor abdominal intenso/continuo, vómito persistente, acumulación de líquidos, sangrado de mucosas, letargia/irritabilidad y hepatomegalia > 2 cm.\n⚡ REPASO ACTIVO\nClasificación Revisada de Dengue (Esquema DENCO):\nDengue sin signos de alarma:\nAntecedente epidemiológico (área endémica o viaje).\nFiebre +$\\ge$2 de: náuseas/vómitos, exantema, mialgias/artralgias, petequias o torniquete (+), leucopenia.\nDengue con signos de alarma (intervención y observación médica estricta):\nDolor abdominal intenso y continuo.\nVómito persistente.\nAcumulación clínica de líquidos.\nSangrado de mucosas.\nLetargia o irritabilidad.\nHepatomegalia > 2 cm.\nLaboratorio: Aumento de hematocrito + rápida caída de plaquetas.\nTumba por dengue:\nEscape de fluidos importantes: Choque (SCD) o acumulación de fluidos con distrés/disnea.\nTumba de Sangrado: Según criterio clínico.\nTumba de daño orgánico: AST/ALT$\\ge$1.000, compromiso de SNC (alteraciones sensitivas), miocardio u otros órganos.\n📖 Referencia:",
