    "id": "semana17_ped_q204",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Sección III: Clasificación Revisada del Dengue, pág. 9 (Figura 2: Diagrama de clasificación del dengue).\nDe acuerdo con la guía clínica, ¿cuál es la definición necesaria para considerar que un paciente con dengue presenta el signo de alarma de vómitos persistentes ?",
    "options": [
      "Dos o más episodios en el transcurso de una hora, o cuatro o más en cuatro horas",
      "Tres o más episodios en una hora, o cinco o más en seis horas",
      "Cuatro o más episodios en una hora, o seis o más en doce horas",
      "Dos episodios acompañados de intolerancia total a líquidos por más de 12 horas",
      "Vómitos continuos que persisten durante más de 24 horas después de ceder la fiebre."
    ],
    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Tres o más episodios en una hora, o cinco o más en seis horas» es la correcta porque la guía define de forma cuantitativa los vómitos persistentes como tres o más episodios en una hora, o cinco o más en seis horas , lo cual impide una adecuada hidratación oral y contribuye a la hipovolemia.\n🔑 CONCEPTOS CLAVE\nFisiopatología del dolor abdominal: Se origina por la extravasación de líquido hacia las zonas pararrenales y perirrenales (irritación de plexos retroperitoneales) y por el engrosamiento de la pared de las asas intestinales bajo la serosa; puede simular cuadros de abdomen agudo quirúrgico o ginecológico.\nAlteración del estado de conciencia: Se define por irritabilidad (inquietud) o somnolencia/letargia, con un puntaje en la escala de coma de Glasgow menor de 15 puntos.\nMonitoreo del hematocrito y plaquetas: El aumento progresivo del hematocrito debe ser concomitante con la disminución progresiva de las plaquetas en al menos dos mediciones consecutivas.\n⚡ REPASO ACTIVO\nDengue sin signos de alarma:\nAdultos: Cuadro florido/típico de varios días (generalmente no más de una semana) seguido de convalecencia prolongada.\nNiños: Puede manifestarse como un \"síndrome febril inespecífico\" donde el nexo epidemiológico es determinante.\nSignos de alarma (Definiciones específicas):\nDolor abdominal intenso y continuo: Por fuga pararrenal/perirrenal y edema subseroso intestinal.\nVómitos persistentes: ≥3 episodios en 1 hora, o≥5 episodios en 6 horas.\nAcumulación de líquidos: Derrame pleural, ascitis o derrame pericárdico (clínico o por imágenes) sin compromiso hemodinámico ni distrés.\nSangrado de mucosas: Encías, nariz, vagina, digestivo (hematemesis, melena) o riñón (hematuria).\nAlteración del estado de conciencia: Irritabilidad, letargia/somnolencia, Glasgow < 15.\nHepatomegalia: Borde hepático palpable > 2 cm por debajo del margen costal.\nLaboratorio: Aumento progresivo de hematocrito concomitante con descenso de plaquetas en al menos dos mediciones.\n📖 Referencia:",
