    "id": "semana17_ped_q206",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Tabla 2 y Sección Dengue grave, pág. 11.\nUn paciente de 30 años residente en una zona con transmisión activa de dengue acude a la urgencia en su 2.° día de fiebre sin foco aparente, cefalea y mialgias intensas. Se solicita una prueba rápida para el antígeno viral NS1, cuyo resultado informa negativo . Según las recomendaciones de la guía clínica, ¿cuál es la conducta diagnóstica y terapéutica correcta?",
    "options": [
      "Descartar la infección por dengue y suspender cualquier medida de seguimiento clínico.",
      "Tratar al paciente como caso de dengue y solicitar serología IgM/IgG a partir del séptimo día.",
      "Solicitar inmediatamente una prueba de detección de anticuerpos IgM por técnica de ELISA.",
      "Indicar aislamiento viral en suero con el fin exclusivo de confirmar la sospecha diagnóstica.",
      "Repetir diariamente la prueba de antígeno NS1 hasta que se confirme la defervescencia clínica."
    ],
    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Tratar al paciente como caso de dengue y solicitar serología IgM/IgG a partir del séptimo día» es la correcta porque un resultado negativo para el antígeno NS1 no descarta la enfermedad, por lo que todo caso sospechoso sin causa aparente debe ser tratado como dengue. Ante un NS1 negativo, es obligatorio solicitar serología IgM - IgG a partir del séptimo día desde el inicio de los síntomas.\n🔑 CONCEPTOS CLAVE\nInterpretación del antígeno NS1: Un resultado positivo durante los primeros 3 días febriles confirma el diagnóstico, pero un resultado negativo nunca lo descarta debido a su sensibilidad variable.\nConducta clínica: Todo paciente con sospecha debe recibir manejo y tratamiento como caso de dengue independientemente de la negatividad de una prueba rápida temprana.\nMomento serológico: La determinación de anticuerpos IgM/IgG debe programarse a partir del séptimo día de evolución para asegurar una sensibilidad diagnóstica adecuada.\n⚡ REPASO ACTIVO\nDefiniciones operativas de caso:\nCaso sospechoso: Fiebre de menos de 7 días de duración sin foco aparente.\nCaso probable: Fiebre aguda de hasta 7 días sin afectación de vías aéreas superiores ni foco, nexo epidemiológico (residencia o viaje a área endémica/vector) y$\\ge$2 manifestaciones (cefalea, dolor retroorbitario, mialgias, artralgias, erupción cutánea, hemorragias leves).\nCaso confirmado: Caso sospechoso con confirmación laboratorial o nexo epidemiológico en contexto de brote/periodo epidémico.\nMétodos de confirmación laboratorial: Seroconversión de IgM/IgG en muestras pareadas, aislamiento de virus, prueba histoquímica o identificación por PCR.\n📖 Referencia:",
