    "id": "semana17_ped_q208",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Tabla 3: Comparación de los diferentes métodos de diagnóstico del dengue, pág. 14.\nPREGUNTA 3 (Pregunta tipo EXCEPTO)\nPara establecer la definición de caso probable de dengue , el paciente debe presentar aparición aguda de fiebre de hasta 7 días de duración sin afección de vías aéreas superiores ni foco aparente, residir o haber viajado a área endémica, y presentar dos o más de las siguientes manifestaciones, EXCEPTO :",
    "options": [
      "Mialgias difusas o artralgias",
      "Cefalea o dolor retroorbitario",
      "Erupción cutánea de distribución variable",
      "Manifestaciones hemorrágicas de carácter leve",
      "Aislamiento viral positivo o seroconversión de IgG"
    ],
    "correctOptionIndex": 4,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nLa opción y es la excepción porque el aislamiento viral y la seroconversión de anticuerpos constituyen criterios para definir un caso confirmado por laboratorio, no forman parte del listado de signos y síntomas clínicos requeridos para catalogar a un paciente como caso probable .\n🔑 CONCEPTOS CLAVE\nCriterios clínicos de caso probable: Requiere el síndrome febril agudo característico (< 7 días sin foco ni compromiso de vía aérea superior) más al menos 2 signos/síntomas cardinales.\nManifestaciones clínicas consideradas: Cefalea, dolor retroorbitario, mialgia, artralgia, erupción cutánea y manifestaciones hemorrágicas leves.\nUtilidad del aislamiento viral: Aunque de infraestructura compleja y lenta (1 a 2 semanas), se realiza principalmente para determinar el serotipo causal en el contexto de un brote.\n⚡ REPASO ACTIVO\nManifestaciones que integran el caso probable (requiere$\\ge$2):\nCefalea.\nDolor retro-orbitario.\nMialgia.\nArtralgia.\nErupción cutánea.\nManifestaciones hemorrágicas leves.\nRequisitos adicionales de caso probable: Fiebre aguda$\\le$7 días sin afección de vías aéreas superiores y sin foco aparente, más antecedente de residencia o viaje a área endémica, transmisión activa o presencia de vector.\n📖 Referencia:",
