    "id": "semana17_ped_q209",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Sección IV: Diagnóstico del Dengue, pág. 13.\nDe acuerdo con la clasificación e interpretación de los métodos de diagnósticos adaptados del Estudio DENCO, ¿cuál de los siguientes resultados clasifica un caso como CONFIRMADO ?",
    "options": [
      "Detección de IgM positiva en una muestra única de suero",
      "Aumento al doble en el título de IgG en muestras pareadas de suero",
      "Reacción en Cadena de la Polimerasa positiva (PCR+)",
      "Detección de IgG positiva en muestra de suero con título de 1:640 por inhibición de la hemaglutinación (IH)",
      "Detección de IgG positiva en muestra única con título de 1:1.280 por inhibición de la hemaglutinación (IH)"
    ],
    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Reacción en Cadena de la Polimerasa positiva (PCR+)» es la correcta porque la detección viral por PCR positiva (PCR+) constituye un criterio definitivo de caso confirmado. La IgM positiva en muestra única o la IgG positiva con título≥1:1.280 por IH en muestra aislada clasifican únicamente como caso \"Altamente Sugestivo\", mientras que para confirmar por IgG pareado se requiere seroconversión o un aumento de al menos 4 veces en el título.\n🔑 CONCEPTOS CLAVE\nCriterios de caso confirmado (DENCO): Requiere PCR positiva, cultivo viral positivo, seroconversión de IgM en suero pareado, o seroconversión/aumento de 4 veces del título de IgG en suero pareado.\nCriterios de caso altamente sugestivo: IgM positiva en una muestra única de suero, o IgG positiva en una muestra de suero con título≥1:1.280 por técnica de inhibición de la hemaglutinación (IH).\nUtilidad del suero pareado: Evalúa la cinética de anticuerpos comparando la fase aguda y convaleciente para corroborar la elevación cuádruple o la aparición de novo de inmunoglobulinas.\n⚡ REPASO ACTIVO\nTabla 4. Interpretación de métodos de diagnóstico en dengue (DENCO):\nAltamente Sugestivo (uno de los siguientes):\nIgM (+) en una muestra de suero.\nIgG (+) en una muestra de suero con título de 1:1.280 o mayor por IH.\nConfirmado (uno de los siguientes):\nPCR (+).\nCultivo viral (+).\nSeroconversión de IgM en suero pareado.\nSeroconversión de IgG en suero pareado o aumento en 4 veces en suero pareado.\n📖 Referencia:",
