    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Manejo ambulatorio en el hogar con paracetamol 15 mg/kg cada 6 horas y control si la fiebre persiste más de 48 horas» es la correcta porque el Grupo A corresponde al manejo ambulatorio en el hogar con aislamiento estricto, paracetamol a 15 mg/kg cada 6 horas para el control térmico, prohibición estricta de salicilatos en menores de 18 años, asegurar hidratación adecuada y acudir a control médico si la fiebre persiste por más de 48 horas.\n🔑 CONCEPTOS CLAVE\nCriterios del Escenario 1 (Grupo A): Cuadro compatible (+) sin factores de riesgo (-), sin signos de alarma (-) y sin insuficiencia respiratoria/inestabilidad (-).\nManejo farmacológico: Paracetamol 15 mg/kg cada 6 horas; contraindicado el uso de salicilatos en menores de 18 años.\nPautas de reconsulta urgente: Explique a los responsables que si presenta disnea, dolor de pecho, esputo hemoptoico, dificultad para alimentarse, confusión o somnolencia, debe acudir de inmediato sin esperar las 24 horas del control.\n⚡ REPASO ACTIVO\nGrupo A - Tratamiento de pacientes con sospecha de COVID-19:\nManejo ambulatorio en el hogar con aislamiento estricto.\nEducación a los responsables sobre signos y síntomas de alarma.\nFibra: Paracetamol 15 mg/kg cada 6 hs.\nAsegurar hidratación adecuada (los lactantes deben continuar con leche materna).\nNo usar salicilatos en menores de 18 años.\nControle al médico si la fiebre persiste por más de 48 horas.\nRegreso urgente si hay: dificultad para respirar, dolor de pecho, esputo con sangre, dificultad para alimentarse, confusión o somnolencia.\n📖 Referencia:",
