    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Hospitalización en hospital distrital en aislamiento individual con hemograma, plaquetas, glicemia, urea, creatinina, GOT y GPT» es la correcta porque los pacientes del Escenario 2 (Grupo B) presentan factores de riesgo de complicaciones sin signos de alarma; deben ser hospitalizados en el hospital distrital en aislamiento en sala individual (o control médico domiciliario diario) y su evaluación laboratorial incluye: hemograma, plaquetas, glicemia, urea, creatinina, GOT y GPT (más radiografía de tórax si hay tos persistentes).\n🔑 CONCEPTOS CLAVE\nCriterios del Escenario 2 (Grupo B): Cuadro compatible (+) con factores de riesgo (+), sin signos de alarma (-) y sin insuficiencia respiratoria/inestabilidad (-).\nFactores de riesgo reconocidos: Edad≤2 años, enfermedad crónica/debilitante, cardiopatías, neumopatías crónicas, diabetes, cáncer, desnutrición, inmunodepresión, IRC, patología neuromuscular y factores sociales (vivir distante sin transporte confiable).\nHidratación y seguimiento: Líquidos por vía oral supervisados ​​(si no tolera, hidratación IV de mantenimiento); reevaluación clínica diaria pasando a Grupo C si surgen signos de alarma.\n⚡ REPASO ACTIVO\nFactores de riesgo para complicaciones:\nEdad≤2 años.\nEnfermedad crónica o debilitante / Cardiopatías / Enfermedad respiratoria crónica.\nDiabetes mellitus / Cáncer / Desnutrición / Depresión inmunológica / Insuficiencia renal crónica.\nEnfermedad neuromuscular.\nCircunstancias sociales (vivir muy distante de la unidad de salud sin transporte confiable).\nManejo Grupo B:\nHospitalización en hospital distrital en aislamiento en sala individual (o control médico domiciliario diario).\nLaboratorio: Hemograma, plaquetas, glicemia, urea, creatinina, GOT, GPT.\nRx de tórax en caso de tos persistente.\nLíquidos VO supervisados ​​(o IV de mantenimiento si no tolera).\nParacetamol 15 mg/kg cada 6 hs.\n📖 Referencia:",
