    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\n«Se administra oxígeno por mascarilla si requiere más de 2 L/min para mantener la saturación por encima del 95%» es la correcta porque el tratamiento de soporte oxigenatorio para el Grupo C estipula suministrar O2 si la saturación es de 95% o menor: mediante bigotera si se requiere 2 L/min o menos, o mediante mascarilla si se requiere > 2 L/min de oxígeno.\n🔑 CONCEPTOS CLAVE\nCriterios del Escenario 3 (Grupo C): Cuadro compatible (+) con presencia de signos de alarma/criterios de gravedad (+), pero sin insuficiencia respiratoria refractaria ni shock (-).\nLugar de internación: Hospital regional o de referencia en aislamiento estricto (sala individual o en cohorte con el mismo diagnóstico).\nTerapéutica médica: O2 para SatO2≤95%, oseltamivir VO si lleva < 48 h de fiebre (por 5 días o hasta confirmación de COVID-19), salbutamol en aerocámara si hay sibilancias, paracetamol 15 mg/kg (hasta 500 mg) cada 6 h, antibióticos ante sospecha de sobreinfección bacteriana y valorar lopinavir/ritonavir.\n⚡ REPASO ACTIVO\nCriterios de Gravedad (Escenario 3 / Grupo C):\nDificultad para respirar / Aumento del trabajo respiratorio.\nHipoxemia: saturación de O2 < 93% respirando aire ambiental.\nDeshidratación o rechazo alimentario / Dificultad para alimentarse.\nExpectoración con sangre.\nConfusión o somnolencia.\nCrepitantes en la auscultación pulmonar / Rx con infiltrados pulmonares.\nCompromiso hemodinámico / Consulta repetida por deterioro clínico.\nTratamiento Grupo C:\nHospitalización en hospital regional/referencia en aislamiento respiratorio y de contacto.\nHidratación de mantenimiento; O2 y SatO2≤95% (bigotera≤2 L/min; mascarilla > 2 L/min).\nOseltamivir VO si < 48 hs de fiebre (5 días o hasta confirmación); salbutamol en aerocámara en sibilancias.\n📖 Referencia:",
