    "text": "Instituto de Medicina Tropical/MSPyBS. CORONAVIRUS COVID-19: Manejo Clínico en Pediatría , 2020. Escenarios 1 al 4 (Grupos A, B, C y D), páginas 11-15.\n¿Cuál de las siguientes afirmaciones sobre los períodos de incubación del virus Chikungunya es correcta según la guía oficial?",
    "options": [
      "El período de incubación extrínseco en el mosquito tiene una duración promedio de 3 a 7 días.",
      "El mosquito es capaz de adquirir el virus de un huésped únicamente durante la fase convaleciente.",
      "En los humanos, los síntomas de la enfermedad aparecen tras un período de incubación intrínseca general de 3 a 7 días (rango: 1-12 días).",
      "El período de incubación intrínseco en el ser humano corresponde a un promedio fijo de 10 días sin rangos variables.",
      "El período de incubación extrínseco es aquel que transcurre desde la picadura del vector hasta el inicio de la viremia en el ser humano."
    ],
    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA «En los humanos, los síntomas de la enfermedad aparecen tras un período de incubación intrínseca general de 3 a 7 días (rango: 1-12 días)» es la correcta porque el texto oficial describe textualmente que, tras la picadura de un mosquito infectado, los síntomas en los humanos se presentan generalmente tras un período de incubación intrínseca de 3 a 7 días, con un rango posible de 1 a 12 días.\n🔑 CONCEPTOS CLAVE\nPeríodo de incubación extrínseco: Se desarrolla en el mosquito y tiene una duración promedio de 10 días tras alimentarse de una persona en fase de viremia.\nPeríodo de incubación intrínseco: Ocurre en el ser humano tras la picadura del mosquito infectado; la clínica se manifiesta generalmente entre 3 y 7 días (rango: 1 a 12 días ).\n⚡ REPASO ACTIVO\n¿Cuánto dura en promedio el período de incubación extrínseco (en el vector)?\n↳ 10 días .\n¿Cuál es el tiempo habitual y el rango del período de incubación intrínseco (en humanos)?\n↳ 3 a 7 días (rango: 1 a 12 días ).\n¿En qué fase el huésped adquiere el virus el mosquito?\n↳ Durante el período de viremia .\n📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: Períodos de incubación, pág. 18 /Figura 1.",
