    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA En la fase subaguda (21 días hasta el final del 3er mes), la radiografía o ecografía de articulaciones sintomáticas resultan prioritarias cuando el análisis clínico no es suficientemente concluyente; a diferencia de la fase aguda donde las imágenes no están indicadas salvo para diagnóstico diferencial, y de la fase crónica (a partir del 4to mes) donde quizás no existen cambios significativos de laboratorio ni radiografías.\n🔑 CONCEPTOS CLAVE\nFase Aguda (5 a 10 días / 1ras 3 semanas): Cuadro sistémico con fiebre, artralgias graves, mialgias, edema, astenia y cambios en laboratorio (leucopenia, plaquetopenia, elevación de PCR, LDH y transaminasas); no se indican imágenes de rutina.\nFase Subaguda (21 días al final del 3er mes): Artralgias inflamatorias, sinovitis con/sin derrame, tenosinovitis, bursitis, lesiones multiformes, astenia y alteraciones neuropsicológicas. Imágenes articulares prioritarias ante clínica no concluyente.\nFase Crónica (≥4to mes / >3 meses): Síntomas persistentes, posible desarrollo de artropatía destructiva (tipo AR/psoriásica) sin alteraciones analíticas ni radiográficas relevantes.\n⚡ REPASO ACTIVO\n¿Qué manifestaciones clínicas adicionales a las articulares aparecen en la fase subaguda?\n↳ Lesiones multiformes, astenia intensa y alteraciones neuropsicológicas.\n¿En qué situación de la fase subaguda se requiere valoración por especialista?\n↳ En casos de poliartritis dolorosa e incapacitante.\n¿Cómo difiere el uso de imágenes entre la fase aguda y subaguda?\n↳ Aguda: no indicadas salvo diagnóstico diferencial. Subaguda: prioritarias si la clínica no es concluyente.\n📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: Tabla 2. Fases clínicas del Chikungunya, pág. 22.",
