    "pagina": "📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: Diagnóstico diferencial con el Dengue, Tabla 5, pág. 25."
