    "tema": "Infectología",
    "subtema": "Chikungunya",
    "subtema_grupo": "Guías Nacionales",
    "module": "Semana 17 - Pediatría",
    "pagina": "📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: 6. Diagnóstico laboratorial de Chikungunya, págs. 27-28 / Figuras 3 y 4."
